        "sr1:03c3359b"
      ]
    },
    {
      "id": "s4",
      "title": "生成月份并查询本地用户",
      "detail": "按当前日期生成 YYYYMM，查询启用用户。",
      "source_ids": [
        "sr1:bb2de8df",
        "sr1:f2e0f5da"
      ]
    },
    {
      "id": "s5",
      "title": "处理用户不存在或停用",
      "detail": "查询为空时抛出用户不存在或已停用异常。",
      "source_ids": [
        "sr1:bb2de8df"
      ]
    },
    {
      "id": "s6",
      "title": "计算并比较密码",
      "detail": "使用运行时选择的 CredentialChecker 计算密码比较值。",
      "source_ids": [
        "sr1:bb2de8df",
        "sr1:77735f96",
        "sr1:bceb96cb",
        "sr1:0e4a18e5"
      ]
    },
    {
      "id": "s7",
      "title": "记录密码错误并通知",
      "detail": "写 BAD_PASSWORD 登录事件，发送失败 MQ 事件并抛出异常。",
      "source_ids": [
        "sr1:bb2de8df",
        "sr1:f2e0f5da",
        "sr1:d89a547e"
      ]
    },
    {
      "id": "s8",
      "title": "记录成功登录并通知",
      "detail": "写 SUCCESS 登录事件，发送成功 MQ 事件。",
      "source_ids": [
        "sr1:bb2de8df",
        "sr1:f2e0f5da",
        "sr1:d89a547e"
      ]
    },
    {
      "id": "s9",
      "title": "返回本地登录结果",
      "detail": "返回 token-{user.id()}，fromSso=false，再由 Controller 封装成 AuthResponse。",
      "source_ids": [
        "sr1:bb2de8df",
        "sr1:4dccc80e"
      ]
    }
  ],
